sys_script_include.script:
var SupplyItemAjax = Class.create();
SupplyItemAjax.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    getItemPrice: function() {
        var itemId = this.getParameter('sysparm_item_id');
        var itemGr = new GlideRecord('x_scope_supply_item');
        if (itemGr.get(itemId)) {
            return itemGr.getValue('price');
        }
        return '0';
    },
    type: 'SupplyItemAjax'
});
